const THREE = require('three');

// Enable with ?debug=1, localhost, or localStorage.setItem('shaderDebug', '1')
const debugEnabled = true

const debugState = {
  webgl: 'init',
  shader: 'init',
  fps: '--',
  error: 'none',
};

let debugEl = null;

function ensureDebugBadge() {
  if (!debugEnabled || debugEl) {
    return;
  }

  debugEl = document.createElement('div');
  debugEl.id = 'shader-debug';
  debugEl.style.position = 'fixed';
  debugEl.style.right = '0.75rem';
  debugEl.style.bottom = '0.75rem';
  debugEl.style.zIndex = '9999';
  debugEl.style.padding = '0.45rem 0.55rem';
  debugEl.style.border = '1px solid #1e3a8a';
  debugEl.style.borderRadius = '6px';
  debugEl.style.background = 'rgba(0, 0, 0, 0.72)';
  debugEl.style.color = '#8ab4ff';
  debugEl.style.font = '12px/1.35 monospace';
  debugEl.style.whiteSpace = 'pre';
  debugEl.style.pointerEvents = 'none';
  document.body.appendChild(debugEl);
}

function renderDebugBadge() {
  if (!debugEnabled) {
    return;
  }
  ensureDebugBadge();
  if (!debugEl) {
    return;
  }

  debugEl.textContent =
    `webgl: ${debugState.webgl}\n` +
    `shader: ${debugState.shader}\n` +
    `fps: ${debugState.fps}\n` +
    `err: ${debugState.error}`;
}

function setDebugError(errorLike) {
  const message = (errorLike && (errorLike.message || String(errorLike))) || 'unknown';
  debugState.error = message.slice(0, 90);
  renderDebugBadge();
}

window.addEventListener('error', (event) => setDebugError(event.error || event.message));
window.addEventListener('unhandledrejection', (event) => setDebugError(event.reason));

// --- Shader Background ---
function initShaderBackground() {
  const canvas = document.createElement('canvas');
  canvas.id = 'bg-shader';
  document.body.prepend(canvas);

  const renderer = new THREE.WebGLRenderer({ canvas, antialias: false });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setClearColor(0x181825, 1);

  const gl = renderer.getContext();
  const webglVersion = gl.getParameter(gl.VERSION);
  debugState.webgl = `ok (${webglVersion})`;

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

  const uniforms = {
    u_time: { value: 0.0 },
    u_resolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) },
  };

  const geometry = new THREE.PlaneGeometry(2, 2);

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */`
      void main() {
        gl_Position = vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      precision highp float;

      uniform float u_time;
      uniform vec2 u_resolution;

      // Catppuccin Mocha palette (from your addon defaults)
      const vec3 background = vec3(24.0 / 255.0, 24.0 / 255.0, 37.0 / 255.0);
      const vec3 element = vec3(17.0 / 255.0, 17.0 / 255.0, 27.0 / 255.0);
      const vec3 text = vec3(205.0 / 255.0, 214.0 / 255.0, 244.0 / 255.0);
      const vec3 secondaryText = vec3(186.0 / 255.0, 194.0 / 255.0, 222.0 / 255.0);
      const vec3 line = vec3(108.0 / 255.0, 112.0 / 255.0, 134.0 / 255.0);
      const vec3 primary = vec3(137.0 / 255.0, 180.0 / 255.0, 250.0 / 255.0); // Blue

      float hash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
      }

      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        vec2 u = f * f * (3.0 - 2.0 * f);
        return mix(
          mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
          mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
          u.y
        );
      }

      float fbm(vec2 p) {
        const mat2 rot = mat2(0.80, 0.60, -0.60, 0.80);
        float v = 0.0;
        float a = 0.5;
        for (int i = 0; i < 5; i++) {
          v += a * noise(p);
          p = rot * p * 2.01;
          a *= 0.5;
        }
        return v;
      }

      float warpedFbm(vec2 p, float t) {
        vec2 q = vec2(
          fbm(p + vec2(0.0, 0.0) + t * 0.12),
          fbm(p + vec2(5.2, 1.3) + t * 0.10)
        );
        vec2 r = vec2(
          fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.08),
          fbm(p + 4.0 * q + vec2(8.3, 2.8) + t * 0.06)
        );
        return fbm(p + 4.0 * r);
      }

      void main() {
        vec2 uv = gl_FragCoord.xy / u_resolution;
        float aspect = u_resolution.x / u_resolution.y;
        vec2 p = vec2(uv.x * aspect, uv.y) * 2.5;

        float t = u_time * 0.4;
        float val = warpedFbm(p, t);

        // Stretch contrast so the shader is visible against the dark Mocha base.
        // Raw FBM output clusters around 0.3-0.6, so remap to the full 0->1 range.
        float v = smoothstep(0.15, 0.85, val);

        // background (near-black) -> primary (blue #89b4fa) -> text (light #cdd6f4)
        // Full-weight mixes — Mocha colors are too dark for fractional blending.
        vec3 col = background;
        col = mix(col, primary,       smoothstep(0.0,  0.55, v));
        col = mix(col, text,          smoothstep(0.5,  0.85, v));
        col = mix(col, secondaryText, smoothstep(0.75, 1.0,  v) * 0.55);
        col = mix(col, line,          smoothstep(0.88, 1.0,  v) * 0.4);

        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });

  const mesh = new THREE.Mesh(geometry, material);
  scene.add(mesh);

  window.addEventListener('resize', () => {
    renderer.setSize(window.innerWidth, window.innerHeight);
    uniforms.u_resolution.value.set(window.innerWidth, window.innerHeight);
  });

  const clock = new THREE.Clock();
  let fpsFrames = 0;
  let fpsWindowStart = performance.now();

  function animate() {
    requestAnimationFrame(animate);

    uniforms.u_time.value = clock.getElapsedTime();
    renderer.render(scene, camera);

    fpsFrames += 1;
    const now = performance.now();
    const elapsed = now - fpsWindowStart;
    if (elapsed >= 500) {
      const fps = (fpsFrames * 1000) / elapsed;
      debugState.fps = fps.toFixed(1);
      fpsFrames = 0;
      fpsWindowStart = now;
      renderDebugBadge();
    }
  }

  debugState.shader = 'running';
  document.documentElement.classList.add('has-shader');
  renderDebugBadge();
  animate();
}

try {
  initShaderBackground();
} catch (error) {
  document.documentElement.classList.remove('has-shader');
  debugState.webgl = 'failed';
  debugState.shader = 'stopped';
  setDebugError(error);
}

// --- Tab visibility: swap title + favicon ---
const hiddenTitle = 'come back :3';
const hiddenFavicon = '/icon.svg';
const originalTitle = document.title;
const faviconEl = document.getElementById('dynamic-favicon');
const originalFavicon = faviconEl ? faviconEl.getAttribute('href') : null;

function updateTabState() {
  const isHidden = document.visibilityState === 'hidden';
  document.title = isHidden ? hiddenTitle : originalTitle;

  if (faviconEl && originalFavicon) {
    faviconEl.setAttribute('href', isHidden ? hiddenFavicon : originalFavicon);
  }
}

if (typeof document.visibilityState === 'string') {
  document.addEventListener('visibilitychange', updateTabState);
}

