precision highp float;

uniform float u_time;
uniform vec2 u_resolution;

const vec3 background = vec3(24.0 / 255.0, 24.0 / 255.0, 37.0 / 255.0);
const vec3 element = vec3(17.0 / 255.0, 17.0 / 255.0, 27.0 / 255.0);
const vec3 text = vec3(205.0 / 255.0, 214.0 / 255.0, 244.0 / 255.0);
const vec3 secondaryText = vec3(186.0 / 255.0, 194.0 / 255.0, 222.0 / 255.0);
const vec3 line = vec3(108.0 / 255.0, 112.0 / 255.0, 134.0 / 255.0);
const vec3 primary = vec3(137.0 / 255.0, 180.0 / 255.0, 250.0 / 255.0); // Blue

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
        u.y
    );
}

float fbm(vec2 p) {
    const mat2 rot = mat2(0.80, 0.60, -0.60, 0.80);
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = rot * p * 2.01;
        a *= 0.5;
    }
    return v;
}

float warpedFbm(vec2 p, float t) {
    vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + t * 0.12),
    fbm(p + vec2(5.2, 1.3) + t * 0.10)
    );
    vec2 r = vec2(
    fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.08),
    fbm(p + 4.0 * q + vec2(8.3, 2.8) + t * 0.06)
    );
    return fbm(p + 4.0 * r);
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    float aspect = u_resolution.x / u_resolution.y;
    vec2 p = vec2(uv.x * aspect, uv.y) * 2.5;

    float t = u_time * 0.4;
    float val = warpedFbm(p, t);

    float v = smoothstep(0.15, 0.85, val);

    vec3 col = background;
    col = mix(col, primary, smoothstep(0.0,  0.55, v));
    col = mix(col, text, smoothstep(0.5,  0.85, v));
    col = mix(col, secondaryText, smoothstep(0.75, 1.0,  v) * 0.55);
    col = mix(col, line, smoothstep(0.88, 1.0,  v) * 0.4);

    gl_FragColor = vec4(col, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec2 u_resolution;

const vec3 background = vec3(24.0 / 255.0, 24.0 / 255.0, 37.0 / 255.0);
const vec3 element = vec3(17.0 / 255.0, 17.0 / 255.0, 27.0 / 255.0);
const vec3 text = vec3(205.0 / 255.0, 214.0 / 255.0, 244.0 / 255.0);
const vec3 secondaryText = vec3(186.0 / 255.0, 194.0 / 255.0, 222.0 / 255.0);
const vec3 line = vec3(108.0 / 255.0, 112.0 / 255.0, 134.0 / 255.0);
const vec3 primary = vec3(137.0 / 255.0, 180.0 / 255.0, 250.0 / 255.0); // Blue

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
        u.y
    );
}

float fbm(vec2 p) {
    const mat2 rot = mat2(0.80, 0.60, -0.60, 0.80);
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = rot * p * 2.01;
        a *= 0.5;
    }
    return v;
}

float warpedFbm(vec2 p, float t) {
    vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + t * 0.12),
    fbm(p + vec2(5.2, 1.3) + t * 0.10)
    );
    vec2 r = vec2(
    fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.08),
    fbm(p + 4.0 * q + vec2(8.3, 2.8) + t * 0.06)
    );
    return fbm(p + 4.0 * r);
}

void main() {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    float aspect = u_resolution.x / u_resolution.y;
    vec2 p = vec2(uv.x * aspect, uv.y) * 2.5;

    float t = u_time * 0.4;
    float val = warpedFbm(p, t);

    float v = smoothstep(0.15, 0.85, val);

    vec3 col = background;
    col = mix(col, primary,       smoothstep(0.0,  0.55, v));
    col = mix(col, text,          smoothstep(0.5,  0.85, v) * 0.45);
    col = mix(col, secondaryText, smoothstep(0.75, 1.0,  v) * 0.30);
    col = mix(col, line,          smoothstep(0.88, 1.0,  v) * 0.20);

    gl_FragColor = vec4(col, 1.0);
}

@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@300;400;500;600&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  color: #1e3a8a;
  font-size: 16px;
  line-height: 1.6;
}

#bg-shader {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  display: block;
}

body {
  font-family: 'Orbitron', 'Courier New', monospace;
  background: transparent;
  color: #1e3a8a;
  padding: 2rem 1rem;
}

header {
  margin-bottom: 3rem;
}

nav {
  display: flex;
  gap: 2rem;
}

nav a {
  text-decoration: none;
  color: #1e3a8a;
  font-weight: 500;
  transition: color 0.2s;
}

nav a:hover {
  color: #60a5fa;
}

main {
  max-width: 800px;
  margin: 0 auto;
}

h1 {
  font-size: 2.5rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
}

h2 {
  font-size: 1.5rem;
  font-weight: 400;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

p {
  margin-bottom: 1rem;
  font-size: 1rem;
}

code {
  background: #111;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-family: 'Orbitron', monospace;
  font-size: 0.9em;
  color: #1e3a8a;
  border: 1px solid #1e3a8a;
}

ul {
  list-style: none;
  margin-bottom: 2rem;
}

li {
  padding: 0.5rem 0;
  font-size: 1rem;
}

li strong {
  font-weight: 500;
  color: #1e3a8a;
}

a {
  color: #1e3a8a;
  text-decoration: none;
  transition: opacity 0.2s;
}

a:hover {
  opacity: 0.7;
  text-decoration: underline;
}

#buttons {
  margin-top: 2rem;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

#buttons a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: transform 0.2s, opacity 0.2s;
  padding: 0.5rem;
  border-radius: 4px;
}

#buttons img {
  max-width: 88px;
  height: auto;
  display: block;
  border-radius: 4px;
  transition: filter 0.2s;
}

#buttons a:hover {
  transform: scale(1.05);
  opacity: 0.85;
}

#buttons a:hover img {
  filter: brightness(1.1);
}

@media (max-width: 600px) {
  body {
    padding: 1rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.25rem;
  }
}

@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@300;400;500;600&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  color: #1e3a8a;
  font-size: 16px;
  line-height: 1.6;
  background: #000;
}

#bg-shader {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  display: block;
}

body {
  font-family: 'Orbitron', 'Courier New', monospace;
  background: transparent;
  color: #1e3a8a;
  padding: 2rem 1rem;
}

header {
  margin-bottom: 3rem;
}

nav {
  display: flex;
  gap: 2rem;
}

nav a {
  text-decoration: none;
  color: #1e3a8a;
  font-weight: 500;
  transition: color 0.2s;
}

nav a:hover {
  color: #60a5fa;
}

main {
  max-width: 800px;
  margin: 0 auto;
}

h1 {
  font-size: 2.5rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
}

h2 {
  font-size: 1.5rem;
  font-weight: 400;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

p {
  margin-bottom: 1rem;
  font-size: 1rem;
}

code {
  background: #111;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-family: 'Orbitron', monospace;
  font-size: 0.9em;
  color: #1e3a8a;
  border: 1px solid #1e3a8a;
}

ul {
  list-style: none;
  margin-bottom: 2rem;
}

li {
  padding: 0.5rem 0;
  font-size: 1rem;
}

li strong {
  font-weight: 500;
  color: #1e3a8a;
}

a {
  color: #1e3a8a;
  text-decoration: none;
  transition: opacity 0.2s;
}

a:hover {
  opacity: 0.7;
  text-decoration: underline;
}

#buttons {
  margin-top: 2rem;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

#buttons a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: transform 0.2s, opacity 0.2s;
  padding: 0.5rem;
  border-radius: 4px;
}

#buttons img {
  max-width: 88px;
  height: auto;
  display: block;
  border-radius: 4px;
  transition: filter 0.2s;
}

#buttons a:hover {
  transform: scale(1.05);
  opacity: 0.85;
}

#buttons a:hover img {
  filter: brightness(1.1);
}

@media (max-width: 600px) {
  body {
    padding: 1rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.25rem;
  }
}

